content.text:
Get this discount engine to 100% branch coverage under c8. Save /workspace/discount/discount.js:

function applyDiscount(cart, code, today) {
  if (!cart || cart.items.length === 0) throw new Error("empty cart");
  const subtotal = cart.items.reduce((s, it) => s + it.cents * it.qty, 0);
  let discount = 0;
  if (code === "SAVE10") {
    discount = Math.floor(subtotal * 0.10);
  } else if (code === "FREESHIP") {
    discount = cart.shippingCents || 0;
  } else if (code && code.startsWith("VIP-")) {
    if (today.getDay() === 0 || today.getDay() === 6) {
      discount = Math.floor(subtotal * 0.25);
    } else {
      discount = Math.floor(subtotal * 0.15);
    }
  } else if (code) {
    throw new Error("unknown code");
  }
  if (discount > 5000) discount = 5000;
  return { subtotal, discount, total: subtotal - discount };
}
module.exports = { applyDiscount };

Set up package.json with c8 and write discount/discount.test.js using node:test. Run npx c8 --branches 100 --functions 100 --lines 100 node --test and iterate until the thresholds pass: null cart, empty items, no code, SAVE10, FREESHIP with and without shippingCents set (the || 0 branch), VIP on a weekend date and a weekday date (construct explicit Date objects like new Date(2026, 2, 7)), unknown code throwing, and the 5000-cent cap engaging. Hand-compute expected numbers in comments. Show the final coverage table in your output.

