const test = require("node:test");
const assert = require("node:assert");
const { applyDiscount } = require("./discount.js");

// Helper: cart with a single item line
const cart = (...items) => ({ items, shippingCents: 0 });
const item = (cents, qty) => ({ cents, qty });

test("null cart throws", () => {
  assert.throws(() => applyDiscount(null, "SAVE10", new Date(2026, 2, 7)), {
    message: "empty cart",
  });
});

test("empty items throws", () => {
  assert.throws(() => applyDiscount({ items: [] }, null, new Date()), {
    message: "empty cart",
  });
});

test("no code: no discount", () => {
  // subtotal = 500 * 2 = 1000; no code -> discount 0
  const r = applyDiscount(cart(item(500, 2)), undefined, new Date(2026, 2, 7));
  assert.deepStrictEqual(r, { subtotal: 1000, discount: 0, total: 1000 });
});

test("SAVE10: 10% off", () => {
  // subtotal = (1200 * 1) + (300 * 3) = 1200 + 900 = 2100
  // discount = floor(2100 * 0.10) = 210
  const r = applyDiscount(
    cart(item(1200, 1), item(300, 3)),
    "SAVE10",
    new Date(2026, 2, 7)
  );
  assert.deepStrictEqual(r, { subtotal: 2100, discount: 210, total: 1890 });
});

test("FREESHIP with shippingCents set", () => {
  // subtotal = 400 * 5 = 2000; discount = shippingCents = 750
  const c = cart(item(400, 5));
  c.shippingCents = 750;
  const r = applyDiscount(c, "FREESHIP", new Date(2026, 2, 7));
  assert.deepStrictEqual(r, { subtotal: 2000, discount: 750, total: 1250 });
});

test("FREESHIP without shippingCents falls back to 0 (|| branch)", () => {
  // subtotal = 250 * 4 = 1000; shippingCents undefined -> discount = || 0
  const c = { items: [item(250, 4)] }; // no shippingCents key
  const r = applyDiscount(c, "FREESHIP", new Date(2026, 2, 7));
  assert.deepStrictEqual(r, { subtotal: 1000, discount: 0, total: 1000 });
});

test("VIP on weekend: 25% off", () => {
  // 2026-03-07 is a Saturday -> getDay() === 6
  // subtotal = 800 * 2 = 1600; discount = floor(1600 * 0.25) = 400
  const r = applyDiscount(
    cart(item(800, 2)),
    "VIP-XYZ",
    new Date(2026, 2, 7)
  );
  assert.deepStrictEqual(r, { subtotal: 1600, discount: 400, total: 1200 });
});

test("VIP on Sunday also takes the weekend branch", () => {
  // 2026-03-08 is a Sunday -> getDay() === 0
  // subtotal = 600 * 1 = 600; discount = floor(600 * 0.25) = 150
  const r = applyDiscount(
    cart(item(600, 1)),
    "VIP-XYZ",
    new Date(2026, 2, 8)
  );
  assert.deepStrictEqual(r, { subtotal: 600, discount: 150, total: 450 });
});

test("VIP on weekday: 15% off", () => {
  // 2026-03-04 is a Wednesday
  // subtotal = 900 * 2 = 1800; discount = floor(1800 * 0.15) = 270
  const r = applyDiscount(
    cart(item(900, 2)),
    "VIP-ABC",
    new Date(2026, 2, 4)
  );
  assert.deepStrictEqual(r, { subtotal: 1800, discount: 270, total: 1530 });
});

test("unknown code throws", () => {
  assert.throws(
    () =>
      applyDiscount(cart(item(100, 1)), "BOGUS", new Date(2026, 2, 7)),
    { message: "unknown code" }
  );
});

test("discount is capped at 5000 cents", () => {
  // Weekend VIP: subtotal = 30000 * 1 = 30000
  // uncapped discount = floor(30000 * 0.25) = 7500 > 5000 -> capped to 5000
  const r = applyDiscount(
    cart(item(30000, 1)),
    "VIP-CAP",
    new Date(2026, 2, 7)
  );
  assert.deepStrictEqual(r, { subtotal: 30000, discount: 5000, total: 25000 });
});

